return {["scripts/actions/weaponskills/heavy_swing.lua"]={["Path"]="scripts/actions/weaponskills/heavy_swing.lua",["SHA256"]="4610d1a24d9ec6725a7b8189ea29c9c406e65aa4175851c4a1c20c36e703b725",["Text"]="-----------------------------------\n-- Heavy Swing\n-- Staff weapon skill\n-- Skill Level: 5\n-- Deacription:Delivers a single-hit attack. Damage varies with TP.\n-- Will stack with Sneak Attack.\n-- Aligned with the Thunder Gorget.\n-- Aligned with the Thunder Belt.\n-- Element: None\n-- Modifiers: STR:30%\n-- 100%TP    200%TP    300%TP\n-- 1.00      1.25      2.25\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 1\n    params.ftpMod = { 1.0, 1.25, 2.25 }\n    params.str_wsc = 0.3\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.str_wsc = 1.0\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/herculean_slash.lua"]={["Path"]="scripts/actions/weaponskills/herculean_slash.lua",["SHA256"]="9f3f4ceabef2ee2dd69f64188e3208fd4240f1f1f993992947b33cec6e17ea5e",["Text"]="-----------------------------------\n-- Herculean Slash\n-- Great Sword weapon skill\n-- Skill Level: 290\n-- Paralyzes target. Duration of effect varies with TP.\n-- Aligned with the Snow Gorget, Thunder Gorget & Breeze Gorget.\n-- Aligned with the Snow Belt, Thunder Belt & Breeze Belt.\n-- Element: Ice\n-- Modifiers: VIT:60%\n-- As this is a magic-based weaponskill it is also modified by Magic Attack Bonus.\n-- 100%TP    200%TP    300%TP\n-- 3.50      3.50      3.50\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params      = {}\n    params.ftpMod     = { 3.5, 3.5, 3.5 }\n    params.vit_wsc    = 0.6\n    params.ele        = xi.element.ICE\n    params.skill      = xi.skill.GREAT_SWORD\n    params.includemab = true\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.vit_wsc = 0.8\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doMagicWeaponskill(player, target, wsID, params, tp, action, primary)\n\n    -- Handle status effect\n    local effectId      = xi.effect.PARALYSIS\n    local actionElement = xi.element.ICE\n    local power         = 30\n    local duration      = math.floor(6 * tp / 100 * applyResistanceAddEffect(player, target, actionElement, 0))\n    xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/hexa_strike.lua"]={["Path"]="scripts/actions/weaponskills/hexa_strike.lua",["SHA256"]="f15d85cdceac5b8bc0aaa7284337aacad61abe5b494ab9bb35f522c6e8070cb7",["Text"]="-----------------------------------\n-- Hexa Strike\n-- Club weapon skill\n-- Skill level: 220\n-- Delivers a six-hit attack. Chance of params.critical varies with TP.\n-- Will stack with Sneak Attack.\n-- Aligned with the Flame Gorget & Light Gorget.\n-- Aligned with the Flame Belt & Light Belt.\n-- Element: None\n-- Modifiers: STR:20%  MND:20%\n-- 100%TP    200%TP    300%TP\n-- 1.00      1.00      1.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 6\n    params.ftpMod = { 1.0, 1.0, 1.0 }\n    params.str_wsc = 0.2\n    params.mnd_wsc = 0.2\n    params.critVaries = { 0.1, 0.3, 0.5 }\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.ftpMod = { 1.125, 1.125, 1.125 }\n        params.str_wsc = 0.3 params.mnd_wsc = 0.3\n        params.multiHitfTP = true\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/hot_shot.lua"]={["Path"]="scripts/actions/weaponskills/hot_shot.lua",["SHA256"]="386cc22bebb0c008101365757cf6ef94faa62eee572e55add6ba83f0823420d7",["Text"]="-----------------------------------\n-- Hot Shot\n-- Marksmanship weapon skill\n-- Skill Level: 5\n-- Deals fire elemental damage to enemy.\n-- Aligned with the Flame Gorget & Light Gorget.\n-- Aligned with the Flame Belt & Light Belt.\n-- Element: Fire\n-- Modifiers: AGI:30%\n-- 100%TP    200%TP    300%TP\n-- 0.50      0.75      1.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 1\n    params.ftpMod = { 0.5, 0.75, 1.0 }\n    params.agi_wsc = 0.3\n    params.hybridWS = true\n    params.ele = xi.element.FIRE\n    params.skill = xi.skill.MARKSMANSHIP\n    params.includemab = true\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.ftpMod = { 0.5, 1.55, 2.1 }\n        params.agi_wsc = 0.7\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doRangedWeaponskill(player, target, wsID, params, tp, action, primary)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/howling_fist.lua"]={["Path"]="scripts/actions/weaponskills/howling_fist.lua",["SHA256"]="73319ef8f9a1102d1537cd3a3fc2f8948c175923395a95296fbdaaf0d686950c",["Text"]="-----------------------------------\n-- Howling Fist\n-- Hand-to-Hand weapon skill\n-- Skill Level: 200\n-- Damage varies with TP.\n-- Will stack with Sneak Attack.\n-- Ignores some defense.\n-- Aligned with the Light Gorget & Thunder Gorget.\n-- Aligned with the Light Belt & Thunder Belt.\n-- Element: None\n-- Modifiers: STR:20%  VIT:50%\n-- 100%TP    200%TP    300%TP\n-- 2.50      2.75      3.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params     = {}\n    params.numHits   = 2\n    params.ftpMod    = { 2.5, 2.75, 3.0 }\n    params.atkVaries = { 1.5, 1.5, 1.5 } -- https://w.atwiki.jp/studiogobli/pages/93.html\n    params.str_wsc   = 0.2\n    params.vit_wsc   = 0.5\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.multiHitfTP = true -- http://wiki.ffo.jp/html/2422.html\n        params.ftpMod = { 2.05, 3.55, 5.75 }\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/impulse_drive.lua"]={["Path"]="scripts/actions/weaponskills/impulse_drive.lua",["SHA256"]="cfc9cf2a8ea14b3a49204da205f58380e42403683857c8049788a54c24317749",["Text"]="-----------------------------------\n-- Impulse Drive\n-- Polearm weapon skill\n-- Skill Level: 240\n-- Delivers a two-hit attack. Damage varies with TP.\n-- In order to obtain Impulse Drive, the quest Methods Create Madness must be completed.\n-- Will stack with Sneak Attack.\n-- Aligned with the Shadow Gorget, Soil Gorget & Snow Gorget.\n-- Aligned with the Shadow Belt, Soil Belt & Snow Belt.\n-- Element: None\n-- Modifiers: STR:50%\n-- 100%TP    200%TP    300%TP\n-- 1.00      1.50      2.50\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 2\n    params.ftpMod = { 1.0, 1.5, 2.5 }\n    params.str_wsc = 0.5\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.ftpMod = { 1.0, 3.0, 5.5 }\n        params.str_wsc = 1.0\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/infernal_scythe.lua"]={["Path"]="scripts/actions/weaponskills/infernal_scythe.lua",["SHA256"]="86965aeac3f07d1ef359dabf7284e8f1463b724925aa0a27eec50ce64fe1a83a",["Text"]="-----------------------------------\n-- Infernal Scythe\n-- Scythe weapon skill\n-- Skill Level: 300\n-- Deals darkness elemental damage and lowers target's attack. Duration of effect varies with TP.\n-- Attack Down effect is -25% attack.\n-- Aligned with the Shadow Gorget & Aqua Gorget.\n-- Aligned with the Shadow Belt & Aqua Belt.\n-- Element: None\n-- Modifiers: STR: 30% INT: 30%\n-- 100%TP    200%TP    300%TP\n-- 3.50        3.50      3.50\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params      = {}\n    params.ftpMod     = { 3.5, 3.5, 3.5 }\n    params.str_wsc    = 0.3\n    params.int_wsc    = 0.3\n    params.ele        = xi.element.DARK\n    params.skill      = xi.skill.SCYTHE\n    params.includemab = true\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.int_wsc = 0.7\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doMagicWeaponskill(player, target, wsID, params, tp, action, primary)\n\n    -- Handle status effect\n    local effectId      = xi.effect.ATTACK_DOWN\n    local actionElement = xi.element.WATER\n    local power         = 25\n    local duration      = math.floor(18 * tp / 100 * applyResistanceAddEffect(player, target, actionElement, 0))\n    xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/insurgency.lua"]={["Path"]="scripts/actions/weaponskills/insurgency.lua",["SHA256"]="ac1758e0659d462f39a5c22f23cfcbc154b20137d79f71a9d7d9b86a36ab8e33",["Text"]="-----------------------------------\n-- Insurgency\n-- Scythe weapon skill\n-- Skill level: N/A\n-- Delivers a fourfold attack. Damage varies with TP. Liberator: Aftermath effect varies with TP.\n-- Available only after completing the Unlocking a Myth (Dark Knight) quest.\n-- Appears to be heavily modified by attack.\n-- Aligned with the Flame Gorget, Light Gorget & Shadow Gorget.\n-- Aligned with the Flame Belt, Light Belt & Shadow Belt.\n-- Element: None\n-- Modifiers: STR:20%  INT:20%\n-- 100%TP    200%TP    300%TP\n-- 0.50      0.75      1.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 4\n    params.ftpMod = { 0.5, 0.75, 1.0 }\n    params.str_wsc = 0.2 params.int_wsc = 0.2\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.ftpMod = { 0.5, 3.25, 6.0 }\n    end\n\n    -- Apply aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.MAIN, xi.aftermath.type.MYTHIC)\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/iron_tempest.lua"]={["Path"]="scripts/actions/weaponskills/iron_tempest.lua",["SHA256"]="0a04d68770b8de0db3b0ae54bdaba0ac9e5f1e88e3494ce28d4b406bec10fcf3",["Text"]="-----------------------------------\n-- Iron Tempest\n-- Great Axe weapon skill\n-- Skill Level: 40\n-- Delivers a single-hit attack. Damage varies with TP.\n-- Will stack with Sneak Attack.\n-- Aligned with the Soil Gorget.\n-- Aligned with the Soil Belt.\n-- Element: None\n-- Modifiers: STR:30%\n-- 100%TP    200%TP    300%TP\n-- 1.00      1.00      1.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 1\n    params.ftpMod = { 1.0, 1.0, 1.0 }\n    params.str_wsc = 0.3\n    params.atkVaries = { 1.0, 2.0, 3.5 }\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.str_wsc = 0.6\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/jishnus_radiance.lua"]={["Path"]="scripts/actions/weaponskills/jishnus_radiance.lua",["SHA256"]="b8254dd4488b64d338040f0bd27eecf5082791267948a59681afc82ee999205d",["Text"]="-----------------------------------\n-- Jishnu's Radiance\n-- Archery weapon skill\n-- Skill level: 357\n-- Empyrean Weapon Skill\n-- RNG Main Job Required\n-- Aligned with the Thunder & Breeze Gorget.\n-- Aligned with the Thunder Belt & Breeze Belt.\n-- Element:\n-- Modifiers: DEX:60%\n-- 100%TP    200%TP    300%TP\n-- 1.75      1.75      1.75\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 3\n    params.ftpMod = { 1.75, 1.75, 1.75 }\n    params.dex_wsc = 0.60\n    params.critVaries = { 0.15, 0.2, 0.25 }\n    params.multiHitfTP = true\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.dex_wsc = 0.8\n    end\n\n    -- Apply aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.RANGED, xi.aftermath.type.EMPYREAN)\n\n    local damage, criticalHit, tpHits, extraHits, shadowsAbsorbed = xi.weaponskills.doRangedWeaponskill(player, target, wsID, params, tp, action, primary)\n\n    if shadowsAbsorbed + tpHits + extraHits == 3 then\n        utils.unused()\n    elseif shadowsAbsorbed + tpHits + extraHits == 2 then\n        utils.unused()\n    end\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/judgment.lua"]={["Path"]="scripts/actions/weaponskills/judgment.lua",["SHA256"]="742f9de7989ba5b211e8d4d466a5e0b946183589fb46edb7c2f5c81ecfaece2d",["Text"]="-----------------------------------\n-- Judgment\n-- Club weapon skill\n-- Were you looking for Judgment Key?\n-- Skill level: 200\n-- Delivers a single-hit attack. Damage varies with TP.\n-- Will stack with Sneak Attack.\n-- Aligned with the Thunder Gorget.\n-- Aligned with the Thunder Belt.\n-- Element: None\n-- Modifiers: STR:32%  MND:32%\n-- 100%TP    200%TP    300%TP\n-- 2.00      2.50      4.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 1\n    params.ftpMod = { 2.0, 2.5, 4.0 }\n    params.str_wsc = 0.32 params.mnd_wsc = 0.32\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.ftpMod = { 3.5, 8.75, 12.0 }\n        params.str_wsc = 0.5 params.mnd_wsc = 0.5\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/keen_edge.lua"]={["Path"]="scripts/actions/weaponskills/keen_edge.lua",["SHA256"]="d52f7fe73a7a74d1e26a6ea1592f22baf8f851d95711b54a7b3510afc2dc1752",["Text"]="-----------------------------------\n-- Keen Edge\n-- Great Axe weapon skill\n-- Skill level: 150\n-- Delivers a single hit attack. Chance of params.critical varies with TP.\n-- Will stack with Sneak Attack.\n-- Aligned with the Shadow Gorget.\n-- Aligned with the Shadow Belt.\n-- Element: None\n-- Modifiers: STR:35%\n-- 100%TP    200%TP    300%TP\n-- 1.00      1.00      1.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 1\n    params.ftpMod = { 1.0, 1.0, 1.0 }\n    params.str_wsc = 0.35\n    params.critVaries = { 0.3, 0.6, 0.9 }\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.str_wsc = 1.0\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/kings_justice.lua"]={["Path"]="scripts/actions/weaponskills/kings_justice.lua",["SHA256"]="7ac08d5f169d8aa4eba2d6f38bc2151321e8a028b038344f1594c7c8316e3304",["Text"]="-----------------------------------\n-- Kings Justice\n-- Great Axe weapon skill\n-- Skill Level: N/A\n-- Delivers a threefold attack. Damage varies with TP. Conqueror: Aftermath effect varies with TP.\n-- Available only after completing the Unlocking a Myth (Warrior) quest.\n-- Aligned with the Breeze Gorget, Thunder Gorget & Soil Gorget.\n-- Aligned with the Breeze Belt, Thunder Belt & Soil Belt.\n-- Element: None\n-- Staff weapon skill Skill level: 10 Delivers a single-hit attack. Damage varies with TP. Element: Non\n-- Modifiers: STR:50%\n-- 100%TP    200%TP    300%TP\n-- 1.00      1.25      1.50\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 3\n    params.ftpMod = { 1.0, 1.25, 1.5 }\n    params.str_wsc = 0.5\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.ftpMod = { 1.0, 3.0, 5.0 }\n    end\n\n    -- Apply aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.MAIN, xi.aftermath.type.MYTHIC)\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/knights_of_rotund.lua"]={["Path"]="scripts/actions/weaponskills/knights_of_rotund.lua",["SHA256"]="89c8099428c9162e4edb8a3bc737bcb8ac8d7e65a78bb701d7265df5af7f61af",["Text"]="-----------------------------------\n-- Knights Of Rotund\n-- Joke Sword Weapon Skill granted by ExcalipoorII\n-- Stat mods unknown\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 1\n    params.ftpMod = { 3.0, 3.0, 3.0 }\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/knights_of_round.lua"]={["Path"]="scripts/actions/weaponskills/knights_of_round.lua",["SHA256"]="b4f284e48f0d1c2b7edcfa805b05adc98a06e6d8c0cb4140f8292e2c3b222b70",["Text"]="-----------------------------------\n-- Knights Of Round\n-- Sword Weapon Skill\n-- Skill Level: N/A\n-- Caliburn/Excalibur: Additional Effect: Regen.\n-- Regen 10HP/Tick, duration varies with TP.\n-- Available only when equipped with the Relic Weapons Caliburn (Dynamis use only) or Excalibur.\n-- Also available without aftermath as a latent effect on Corbenic Sword.\n-- Aligned with the Flame Gorget & Light Gorget.\n-- Aligned with the Flame Belt & Light Belt.\n-- Element: None\n-- Modifiers: STR:40%  MND:40%\n-- 100%TP    200%TP    300%TP\n-- 3.00      3.00      3.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 1\n    params.ftpMod = { 3.0, 3.0, 3.0 }\n    params.str_wsc = 0.4 params.mnd_wsc = 0.4\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.ftpMod = { 5.0, 5.0, 5.0 }\n    end\n\n    -- Apply aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.MAIN, xi.aftermath.type.RELIC)\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/last_stand.lua"]={["Path"]="scripts/actions/weaponskills/last_stand.lua",["SHA256"]="0c626cd2d912c089455920672216700b8ec8de964bbee9006ba12a7aeb2c2090",["Text"]="-----------------------------------\n-- Last Stand\n-- Skill Level: 357\n-- Description: Attacks once or twice, depending on remaining ammunition. Damage dealt varies with TP.\n-- If the first shot of the weapon skill does enough damage to defeat the target, the second shot will not be used.\n-- To obtain Last Stand, the quest Martial Mastery must be completed.\n-- This Weapon Skill's first hit fTP is duplicated for all additional hits.\n-- Aligned with the Flame Gorget, Light Gorget & Aqua Gorget.\n-- Properties\n-- Element: N/A\n-- Skillchain Properties: Fusion/Reverberation\n-- Modifiers: AGI:100%\n-- Damage Multipliers by TP:\n-- 100%TP    200%TP    300%TP\n--   2.0    2.125    2.25\n\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 2\n    params.ftpMod = { 2.0, 2.125, 2.25 }\n    params.agi_wsc = player:getMerit(xi.merit.LAST_STAND) * 0.17\n    params.multiHitfTP = true\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.ftpMod = { 2.0, 3.0, 4.0 }\n        params.agi_wsc = 0.7 + (player:getMerit(xi.merit.LAST_STAND) * 0.03)\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doRangedWeaponskill(player, target, wsID, params, tp, action, primary)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/leaden_salute.lua"]={["Path"]="scripts/actions/weaponskills/leaden_salute.lua",["SHA256"]="31366fe1fbcff6877cf1d0ee12141e8017a2e6f9823fe54c35c96b2dfc51d91a",["Text"]="-----------------------------------\n-- Leaden Salute\n-- Sword weapon skill\n-- Skill Level: N/A\n-- Delivers a Twofold attack. Damage varies with TP. Death Penalty: Aftermath effect varies with TP.\n-- Available only after completing the Unlocking a Myth (Corsair) quest.\n-- Aligned with the Shadow Gorget, Soil Gorget & Light Gorget.\n-- Aligned with the Shadow Belt, Soil Belt & Light Belt.\n-- Element: Darkness\n-- Modifiers: AGI:30%\n-- 100%TP    200%TP    300%TP\n-- 4.00      4.25      4.75\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.ftpMod = { 4.0, 4.25, 4.75 }\n    params.agi_wsc = 0.3\n    params.ele = xi.element.DARK\n    params.skill = xi.skill.MARKSMANSHIP\n    params.includemab = true\n    params.dStat = xi.mod.AGI\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.ftpMod = { 4.0, 6.7, 10.0 }\n        params.agi_wsc = 1.0\n    end\n\n    -- Apply Aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.RANGED, xi.aftermath.type.MYTHIC)\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doMagicWeaponskill(player, target, wsID, params, tp, action, primary)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/leg_sweep.lua"]={["Path"]="scripts/actions/weaponskills/leg_sweep.lua",["SHA256"]="1e7743dc5efef0487da9bfb4b96163ff979b2467deaa1f69b0ff1a298c59c550",["Text"]="-----------------------------------\n-- Leg Sweep\n-- Polearm weapon skill\n-- Skill Level: 100\n-- Stuns enemy. Chance of stunning varies with TP.\n-- Will stack with Sneak Attack.\n-- Aligned with the Thunder Gorget.\n-- Aligned with the Thunder Belt.\n-- Element: None\n-- Modifiers: STR:30%\n-- 100%TP    200%TP    300%TP\n-- 1.00      1.00      1.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 1\n    params.ftpMod  = { 1, 1, 1 }\n    params.str_wsc = 0.3\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.str_wsc = 1\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    -- Handle status effect\n    if math.randomInt(1, 100) <= tp / 30 * applyResistanceAddEffect(player, target, xi.element.THUNDER, 0) then\n        local effectId      = xi.effect.STUN\n        local actionElement = xi.element.THUNDER\n        local power         = 1\n        local duration      = math.floor(4 * applyResistanceAddEffect(player, target, actionElement, 0))\n        xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n    end\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/mandalic_stab.lua"]={["Path"]="scripts/actions/weaponskills/mandalic_stab.lua",["SHA256"]="914e3740e33173ba08c9f45ed114e24820a3bc20ff8634d814e8fd8be3cfe687",["Text"]="-----------------------------------\n-- Mandalic Stab\n-- Dagger weapon skill\n-- Skill Level: N/A\n-- Damage Varies with TP. Vajra: Aftermath effect varies with TP.\n-- Multiplies attack by 1.66\n-- Available only after completing the Unlocking a Myth (Thief) quest.\n-- Will stack with Sneak Attack.\n-- Aligned with the Shadow Gorget, Flame Gorget & Light Gorget.\n-- Aligned with the Shadow Belt, Flame Belt & Light Belt.\n-- Element: None\n-- Modifiers: DEX:30%\n-- 100%TP    200%TP    300%TP\n-- 2.00      2.13      2.50\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 1\n    params.ftpMod = { 2.0, 2.13, 2.5 }\n    params.dex_wsc = 0.3\n    params.atkVaries = { 1.66, 1.66, 1.66 }\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.ftpMod = { 4.0, 6.09, 8.5 }\n        params.dex_wsc = 0.6\n        params.atkVaries = { 1.75, 1.75, 1.75 }\n    end\n\n    -- Apply aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.MAIN, xi.aftermath.type.MYTHIC)\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/mercy_stroke.lua"]={["Path"]="scripts/actions/weaponskills/mercy_stroke.lua",["SHA256"]="2e0c4fd69e7b9994074a24a4a8d18956d5d5f693b671e4ed13e6746e3692ec23",["Text"]="-----------------------------------\n-- Mercy Stroke\n-- Dagger weapon skill\n-- Skill level: N/A\n-- Batardeau/Mandau: Temporarily improves params.critical hit rate.\n-- Aftermath gives +5% params.critical hit rate.\n-- Must have Batardeau, Mandau, or Clement Skean equipped.\n-- Aligned with the Shadow Gorget & Soil Gorget.\n-- Aligned with the Shadow Belt & Soil Belt.\n-- Element: None\n-- Modifiers: STR:60%\n-- 100%TP    200%TP    300%TP\n-- 3.00      3.00      3.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 1\n    params.ftpMod = { 3.0, 3.0, 3.0 }\n    params.str_wsc = 0.6\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.ftpMod = { 5.0, 5.0, 5.0 }\n        params.str_wsc = 0.8\n    end\n\n    -- Apply aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.MAIN, xi.aftermath.type.RELIC)\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/metatron_torment.lua"]={["Path"]="scripts/actions/weaponskills/metatron_torment.lua",["SHA256"]="f50efbf85a749c0864326a7fc28409fd552cc40e21db5c6fc4827ad81cbb0767",["Text"]="-----------------------------------\n-- Metatron Torment\n-- Hand-to-Hand Skill level: 5 Description: Delivers a threefold attack. Damage varies wit weapon skill\n-- Great Axe Weapon Skill\n-- Skill Level: N/A\n-- Lowers target's defense. Additional effect: temporarily lowers damage taken from enemies.\n-- Defense Down effect is 18.5%, 1 minute duration.\n-- Damage reduced is 20.4% or 52/256.\n-- Lasts 20 seconds at 100TP, 40 seconds at 200TP and 60 seconds at 300TP.\n-- Available only when equipped with the Relic Weapons Abaddon Killer (Dynamis use only) or Bravura.\n-- Also available as a Latent effect on Barbarus Bhuj\n-- Since these Relic Weapons are only available to Warriors, only Warriors may use this Weapon Skill.\n-- Aligned with the Flame Gorget & Light Gorget.\n-- Aligned with the Flame Belt & Light Belt.\n-- Element: None\n-- Modifiers: STR:60%\n-- 100%TP    200%TP    300%TP\n-- 2.75      2.75      2.75\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 1\n    params.ftpMod  = { 2.75, 2.75, 2.75 }\n    params.str_wsc = 0.6\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.str_wsc = 0.8\n    end\n\n    -- Apply aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.MAIN, xi.aftermath.type.RELIC)\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    -- Handle status effect\n    local effectId      = xi.effect.DEFENSE_DOWN\n    local actionElement = xi.element.WIND\n    local power         = 19\n    local duration      = math.floor(120 * applyResistanceAddEffect(player, target, actionElement, 0))\n    xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/mistral_axe.lua"]={["Path"]="scripts/actions/weaponskills/mistral_axe.lua",["SHA256"]="9b0c3225cccc229bacb49f181f2bad01639ac983b231d4c1927ad3963aefc034",["Text"]="-----------------------------------\n-- Mistral Axe\n-- Axe weapon skill\n-- Skill level: 225 (Beastmasters and Warriors only.)\n-- Delivers a single-hit ranged attack at a maximum distance of 15.7'. Damage varies with TP.\n-- Despite being able to be used from a distance it is considered a melee attack and can be stacked with Sneak Attack and/or Trick Attack\n-- Aligned with the Flame Gorget & Light Gorget.\n-- Aligned with the Flame Belt & Light Belt.\n-- Element: None\n-- Modifiers: STR:50%\n-- 100%TP    200%TP    300%TP\n-- 2.50      3.00      3.50\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 1\n    params.ftpMod = { 2.5, 3.0, 3.5 }\n    params.str_wsc = 0.5\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.ftpMod = { 4.0, 10.5, 13.625 }\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/moonlight.lua"]={["Path"]="scripts/actions/weaponskills/moonlight.lua",["SHA256"]="658991ced769416ecd02b4534fed4513df99073e8bf13078bd7b36c16b64c34b",["Text"]="-----------------------------------\n-- Moonlight\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local lvl = player:getSkillLevel(11) -- get club skill\n    local damage = (lvl / 9) - 1\n    local damagemod = damage * ((50 + (tp * 0.05)) / 100)\n    damagemod = damagemod * xi.settings.main.WEAPON_SKILL_POWER\n    return 1, 0, false, damagemod\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/mordant_rime.lua"]={["Path"]="scripts/actions/weaponskills/mordant_rime.lua",["SHA256"]="90740bc90188aff2b07298da5272de3470a33671b85727448d6dddeacdbe2172",["Text"]="-----------------------------------\n-- Mordant Rime\n-- Dagger weapon skill\n-- Skill level: N/A\n-- Description: Delivers a twofold attack that decreases target's movement speed. Chance of decreasing movement speed varies with TP. Carnwenhan: Aftermath effect varies with TP.\n-- Aligned with the Breeze Gorget, Thunder Gorget, Aqua Gorget & Snow Gorget.\n-- Aligned with the Breeze Belt, Thunder Belt, Aqua Belt & Snow Belt.\n-- Element: None\n-- Skillchain Properties: Fragmentation/Distortion\n-- Modifiers: DEX:30%  CHR:70%\n-- Damage Multipliers by TP:\n-- 100%TP    200%TP    300%TP\n-- 5.0        5.0        5.0\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 2\n    params.ftpMod  = { 3, 3, 3 }\n    params.dex_wsc = 0.3\n    params.chr_wsc = 0.5\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.ftpMod  = { 5, 5, 5 }\n        params.chr_wsc = 0.7\n    end\n\n    -- Apply aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.MAIN, xi.aftermath.type.MYTHIC)\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    -- Handle status effect\n    if math.randomInt(1, 100) <= tp / 30 * applyResistanceAddEffect(player, target, xi.element.THUNDER, 0) then\n        local effectId      = xi.effect.WEIGHT\n        local actionElement = xi.element.WIND\n        local power         = 25\n        local duration      = math.floor(60 * applyResistanceAddEffect(player, target, actionElement, 0))\n        xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n    end\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/myrkr.lua"]={["Path"]="scripts/actions/weaponskills/myrkr.lua",["SHA256"]="d7ce36d6532ed0eb42e0b07e66a785db564e7e95a8b9bd889cb68aa23f9238c2",["Text"]="-----------------------------------\n-- Myrkr\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    -- Apply aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.MAIN, xi.aftermath.type.EMPYREAN)\n\n    local ftpmp = xi.weaponskills.fTP(tp, { 0.2, 0.4, 0.6 })\n    return 1, 0, false, ftpmp * player:getMaxMP()\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/mystic_boon.lua"]={["Path"]="scripts/actions/weaponskills/mystic_boon.lua",["SHA256"]="221f5e4c3f4eca95fda56e987f686cbb322c6085ce825a3f426c69f4d6781718",["Text"]="-----------------------------------\n-- Mystic Boon\n-- Club weapon skill\n-- Skill level: N/A\n-- Converts damage dealt to own MP. Damage varies with TP. Yagrush: Aftermath effect varies with TP.\n-- Available only after completing the Unlocking a Myth (White Mage) quest.\n-- Damage is significantly affected by Attack. Verification Needed\n-- Not aligned with any \"elemental gorgets\" or elemental belts due to it's absence of Skillchain properties.\n-- Element: None\n-- Modifiers: STR:30%  MND:70%\n-- 100%TP    200%TP    300%TP\n-- 2.5        4.0        7.0\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 1\n    params.ftpMod = { 1.0, 1.5, 2.0 }\n    params.str_wsc = 0.3\n    params.mnd_wsc = 0.5\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.ftpMod = { 2.5, 4.0, 7.0 }\n        params.mnd_wsc = 0.7\n    end\n\n    -- Apply aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.MAIN, xi.aftermath.type.MYTHIC)\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    player:addMP(damage)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/namas_arrow.lua"]={["Path"]="scripts/actions/weaponskills/namas_arrow.lua",["SHA256"]="047080222de8e8a3bb7bed04972a96c52dce2b6f78fd8a0b55294dcdd30f88cc",["Text"]="-----------------------------------\n-- Namas Arrow\n-- Skill Level: N/A\n-- Description: Additional Effect: Temporarily improves Ranged Accuracy\n-- Aligned with the Light Gorget, Snow Gorget & Aqua Gorget.\n-- Properties\n-- Element: N/A\n-- Skillchain Properties: Light/Distortion\n-- Modifiers: STR: 40% AGI: 40%\n-- Damage Multipliers by TP:\n-- 100%TP    200%TP    300%TP\n--   2.75    2.75    2.75\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 1\n    params.ftpMod = { 2.75, 2.75, 2.75 }\n    params.str_wsc = 0.4\n    params.agi_wsc = 0.4\n    params.overrideCE = 160\n    params.overrideVE = 480\n    params.rangedAccuracyBonus = 100 -- https://wiki.ffo.jp/html/3094.html 特性の有無で100近く飛命が低い侍であっても問題なくとてとてに当てられるほど。\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doRangedWeaponskill(player, target, wsID, params, tp, action, primary)\n\n    -- Apply aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.RANGED, xi.aftermath.type.RELIC)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/nightmare_scythe.lua"]={["Path"]="scripts/actions/weaponskills/nightmare_scythe.lua",["SHA256"]="1f86e69e59a5665877f78af93e43334432ca1daad31398f16386eec5f9b45823",["Text"]="-----------------------------------\n-- Nightmare Scythe\n-- Scythe weapon skill\n-- Skill Level: 100\n-- Blinds enemy. Duration of effect varies with TP.\n-- Will stack with Sneak Attack.\n-- Aligned with the Shadow Gorget & Soil Gorget.\n-- Aligned with the Shadow Belt & Soil Belt.\n-- Element: None\n-- Modifiers: STR:60%  MND:60%\n-- 100%TP    200%TP    300%TP\n-- 1.00      1.00      1.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 1\n    params.ftpMod  = { 1, 1, 1 }\n    params.str_wsc = 0.3\n    params.mnd_wsc = 0.3\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.str_wsc = 0.6\n        params.mnd_wsc = 0.6\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    -- Handle status effect\n    local effectId      = xi.effect.BLINDNESS\n    local actionElement = xi.element.DARK\n    local power         = 20\n    local duration      = math.floor(6 * tp / 100 * applyResistanceAddEffect(player, target, actionElement, 0))\n    xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/numbing_shot.lua"]={["Path"]="scripts/actions/weaponskills/numbing_shot.lua",["SHA256"]="26e6dd7a73f7ca189e7149ab67c6ba3b6e2663f188496287d340f1f065264f98",["Text"]="-----------------------------------\n-- Numbing Shot\n-- Marksmanship weapon skill\n-- Skill level: 290\n-- Main of sub must be Ranger or Corsair\n-- Aligned with the Thunder & Breeze Gorget.\n-- Aligned with the Thunder Belt & Breeze Belt.\n-- Element: Ice\n-- Modifiers: AGI 80%\n-- 100%TP    200%TP    300%TP\n-- 3.00      3.00      3.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 1\n    params.ftpMod  = { 3, 3, 3 }\n    params.agi_wsc = 0.6\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.agi_wsc = 0.8\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doRangedWeaponskill(player, target, wsID, params, tp, action, primary)\n\n    -- Handle status effect\n    local effectId      = xi.effect.PARALYSIS\n    local actionElement = xi.element.ICE\n    local power         = 30\n    local duration      = math.floor(6 * tp / 100 * applyResistanceAddEffect(player, target, actionElement, 0))\n    xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/omniscience.lua"]={["Path"]="scripts/actions/weaponskills/omniscience.lua",["SHA256"]="a28017ff77768da528b9da696284e7dae0201475cd929c5881fb5dd72f854c2a",["Text"]="-----------------------------------\n-- Omniscience\n-- Staff weapon skill\n-- Skill Level: N/A\n-- Lowers target's magic attack. Duration of effect varies with TP. Tupsimati: Aftermath effect varies with TP.\n-- Reduces enemy's magic attack by -10.\n-- Available only after completing the Unlocking a Myth (Scholar) quest.\n-- Aligned with the Shadow Gorget, Soil Gorget & Light Gorget.\n-- Aligned with the Shadow Belt, Soil Belt & Light Belt.\n-- Element: Dark\n-- Modifiers: MND:80%\n-- 100%TP    200%TP    300%TP\n-- 2.00      2.00      2.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params      = {}\n    params.ftpMod     = { 2, 2, 2 }\n    params.mnd_wsc    = 0.3\n    params.ele        = xi.element.DARK\n    params.skill      = xi.skill.STAFF\n    params.includemab = true\n    -- params.dStat = xi.mod.MND (pMND-mMND)×2 (Not supported in weaponskills.lua currently)\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.mnd_wsc = 0.8\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doMagicWeaponskill(player, target, wsID, params, tp, action, primary)\n\n    -- Apply Aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.MAIN, xi.aftermath.type.MYTHIC)\n\n    -- Handle status effect\n    local effectId      = xi.effect.MAGIC_ATK_DOWN\n    local actionElement = xi.element.DARK\n    local power         = 10\n    local duration      = math.floor(6 * tp / 100 * applyResistanceAddEffect(player, target, actionElement, 0))\n    xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/one_inch_punch.lua"]={["Path"]="scripts/actions/weaponskills/one_inch_punch.lua",["SHA256"]="4e8aa680f7187bfcdbb4deba075ca1067e0eb43bc3e058f469b5c9f606b31660",["Text"]="-----------------------------------\n-- One Inch Punch\n-- Hand-to-Hand weapon skill\n-- Skill level: 75\n-- Delivers an attack that ignores target's defense. Amount ignored varies with TP.\n-- Will stack with Sneak Attack.\n-- Aligned with the Shadow Gorget.\n-- Aligned with the Shadow Belt.\n-- Element: None\n-- Modifiers: VIT:40%\n-- 100%TP    200%TP    300%TP\n-- 1.00      1.00      1.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 2\n    params.ftpMod = { 1.0, 1.0, 1.0 }\n    params.vit_wsc = 0.4\n    -- Defense ignored is 0%, 30%, 50% as per http://www.bg-wiki.com/bg/One_Inch_Punch\n    params.ignoredDefense = { 0.0, 0.3, 0.5 }\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.multiHitfTP = true -- http://wiki.ffo.jp/html/2418.html\n        params.vit_wsc = 1.0\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/onslaught.lua"]={["Path"]="scripts/actions/weaponskills/onslaught.lua",["SHA256"]="9a517a6292da1ce19ceb31a8c09a42f5abd9ad17e040a2608132bd680865dbb5",["Text"]="-----------------------------------\n-- Onslaught\n-- Axe weapon skill\n-- Skill Level: N/A\n-- Lowers target's params.accuracy. Additional effect: temporarily increases Attack.\n-- Available only when equipped with the Relic Weapons Ogre Killer (Dynamis use only) or Guttler or Cleofun Axe (with Latent active).\n-- These Relic Weapons are only available to Beastmasters, so only they can use this Weapon Skill.\n-- One hit attack despite of non single-hit animation\n-- The attack increase seems to be 10%.\n-- Aligned with the Shadow Gorget & Soil Gorget.\n-- Aligned with the Shadow Belt & Soil Belt.\n-- Element: None\n-- Modifiers: DEX:80%\n-- 100%TP    200%TP    300%TP\n-- 2.75      2.75      2.75\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 1\n    params.ftpMod  = { 2.75, 2.75, 2.75 }\n    params.dex_wsc = 0.6\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.dex_wsc = 0.8\n    end\n\n    -- Apply aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.MAIN, xi.aftermath.type.RELIC)\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    -- Handle status effect\n    local effectId      = xi.effect.ACCURACY_DOWN\n    local actionElement = xi.element.EARTH\n    local power         = 30\n    local duration      = math.floor(120 * applyResistanceAddEffect(player, target, actionElement, 0))\n    xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"}};
